// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/checks", wrapper.ListChecks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/checks/{check_id}", wrapper.GetCheck)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/exceptions", wrapper.ListOrderExceptions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/exceptions/{exception_id}", wrapper.GetOrderException)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/projection-digests", wrapper.GetOrdersProjectionDigest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reports/cancellations", wrapper.GetCancellationReport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reports/kitchen-times", wrapper.GetKitchenTimeReport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reports/kot-log", wrapper.GetKotLog)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reports/open-checks", wrapper.GetOpenChecksReport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reports/present-log", wrapper.GetPresentLog)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/internal/v1/outlets/{outlet_id}/open-check-count", wrapper.GetOpenCheckCount)

	return m
}
